@paginate(PAGINATION_MODEL)
def describe_cache_clusters(
    self,
    cache_cluster_id: str,
    max_records: int,
    marker: str,
) -> List[CacheCluster]:
    if max_records is None:
        max_records = 100
    if cache_cluster_id:
        if cache_cluster_id in self.cache_clusters:
            cache_cluster = self.cache_clusters[cache_cluster_id]
            return list([cache_cluster])
        else:
            raise CacheClusterNotFound(cache_cluster_id)

    # Get all cache clusters except the default one
    cache_clusters = []
    for cluster_id, cluster in self.cache_clusters.items():
        if cluster_id != "default":
            cache_clusters.append(cluster)

    # Sort the cache clusters by ID to ensure consistent ordering
    cache_clusters.sort(key=lambda x: x.cache_cluster_id)

    return cache_clusters
